// Constants used for the message buffer size, simulating what might be defined elsewhere
const PPK_ASSERT_MESSAGE_BUFFER_SIZE: usize = 1024;
const PPK_ASSERT_EXCEPTION_MESSAGE_BUFFER_SIZE: usize = 1024;

type PrintHandler = fn(
    out: &mut dyn Write,
    level: i32,
    format: &str,
    args: std::fmt::Arguments,
) -> Result<(), std::io::Error>;

#[derive(Debug, PartialEq, Eq)]
enum AssertLevel {
    Debug,
    Warning,
    Error,
    Fatal,
}

#[derive(Debug, PartialEq, Eq)]
enum AssertAction {
    None,
    Abort,
    Ignore,
    IgnoreLine,
    IgnoreAll,
    Break,
    Throw,
}

static mut HANDLER: AssertHandler = default_handler;

type AssertHandler = fn(
    file: &str,
    line: i32,
    function: &str,
    expression: &str,
    level: i32,
    message: Option<&str>,
) -> AssertAction;

struct AssertionException {
    file: String,
    line: i32,
    function: String,
    expression: String,
    message: Option<String>,
}

impl AssertionException {
    fn new(
        file: &str,
        line: i32,
        function: &str,
        expression: &str,
        message: Option<&str>,
    ) -> Self {
        let message = message.map(|msg| msg.to_owned());
        AssertionException {
            file: file.to_owned(),
            line,
            function: function.to_owned(),
            expression: expression.to_owned(),
            message,
        }
    }

    fn what(&self) -> String {
        match &self.message {
            Some(msg) => msg.clone(),
            None => String::new(),
        }
    }
}

fn print(out: &mut dyn Write, level: i32, format: &str, args: std::fmt::Arguments) -> Result<(), std::io::Error> {
    write!(out, "{}: ", level_to_string(level))?;
    write!(out, "{}", args)?;
    writeln!(out)?;

    #[cfg(windows)]
    {
        let buffer = std::fmt::format(format_args!(format, args));
        let cstr = CString::new(buffer).unwrap();
        unsafe {
            OutputDebugStringA(cstr.as_ptr());
        }
    }

    #[cfg(android)]
    {
        let log_level = level_to_android_log_level(level);
        android_logger::init_once(Config::default().with_min_level(log_level.to_level_filter()));
        log::log!(log_level, "{}", std::fmt::format(format_args!(format, args)));
    }

    Ok(())
}

fn level_to_string(level: i32) -> &'static str {
    match level {
        0 => "DEBUG",
        1 => "WARNING",
        2 => "ERROR",
        3 => "FATAL",
        _ => "UNKNOWN",
    }
}

#[cfg(android)]
fn level_to_android_log_level(level: i32) -> Level {
    match level {
        0 => Level::Debug,
        1 => Level::Warn,
        2 => Level::Error,
        3 => Level::Error, // No fatal in Android levels
        _ => Level::Info,
    }
}

fn format_level(
    level: i32,
    expression: &str,
    out: &mut dyn Write,
    print: PrintHandler,
) -> Result<(), std::io::Error> {
    let levelstr = level_to_string(level);
    print(out, level, "Assertion '{}' failed ({})\n", format_args!("{} ({})", expression, levelstr))
}

fn default_handler(
    file: &str,
    line: i32,
    function: &str,
    expression: &str,
    level: i32,
    message: Option<&str>,
) -> AssertAction {
    #[cfg(windows)]
    {
        if unsafe { GetConsoleWindow() } == std::ptr::null_mut() {
            unsafe {
                AllocConsole();
                // Placeholders for redirection; Normally this will require FFI
                // but in Rust context is ignored
                // freopen("CONIN$", "r", std::ptr::null_mut());
                // freopen("CONOUT$", "w", std::ptr::null_mut());
            }
        }
    }

    if let Some(msg) = message {
        let mut stderr = std::io::stderr();
        let _ = format_level(level, expression, &mut stderr, print);
        let _ = print(&mut stderr, level, "  in file {}, line {}\n  function: {}\n", format_args!("{} {} {}", file, line, function));
        let _ = print(&mut stderr, level, "  with message: {}\n\n", format_args!("{}", msg));
    }

    if level < AssertLevel::Debug as i32 {
        AssertAction::None
    } else if (AssertLevel::Debug as i32..AssertLevel::Error as i32).contains(&level) {
        #[cfg(all(not(target_os = "ios"), not(android), not(feature = "disable_ignore")))]
        {
            let mut buffer = String::new();
            loop {
                let _ = std::io::Write::write(&mut std::io::stderr(), b"Press (I)gnore / Ignore (A)ll / (D)ebug / A(b)ort: ");
                let _ = std::io::Write::flush(&mut std::io::stderr());

                if std::io::stdin().read_line(&mut buffer).is_ok() {
                    let input = buffer.chars().next().unwrap().to_ascii_lowercase();
                    match input {
                        'i' => return AssertAction::Ignore,
                        'd' => return AssertAction::Break,
                        'b' => return AssertAction::Abort,
                        'a' => return AssertAction::IgnoreAll,
                        _ => continue,
                    }
                }
            }
        }
        #[cfg(feature = "disable_ignore")]
        {
            AssertAction::Break
        }
    } else if (AssertLevel::Error as i32..AssertLevel::Fatal as i32).contains(&level) {
        AssertAction::Throw
    } else {
        AssertAction::Abort
    }
}

fn throw_exception(exc: AssertionException) {
    panic!(
        "Assertion failed: {} at {}:{} ({}) with message: {}",
        exc.expression, exc.file, exc.line, exc.function, exc.what()
    );
}

fn set_assert_handler(handler: AssertHandler) -> AssertHandler {
    unsafe {
        let previous_handler = HANDLER;
        HANDLER = handler;
        previous_handler
    }
}

fn handle_assert(
    file: &str,
    line: i32,
    function: &str,
    expression: &str,
    level: i32,
    ignore_line: &mut bool,
    message: Option<&str>,
) -> AssertAction {
    let mut message_buffer = String::new();
    if let Some(msg) = message {
        let va_list = format!("{:?}", msg); // Mimic variable argument list
        message_buffer.push_str(&va_list);
    }

    let file_name = file.rsplit('/').next().unwrap_or(file);

    let action = unsafe { HANDLER(file_name, line, function, expression, level, Some(&message_buffer)) };

    match action {
        AssertAction::Abort => std::process::abort(),
        #[cfg(not(feature = "disable_ignore"))]
        AssertAction::IgnoreLine => *ignore_line = true,
        AssertAction::IgnoreAll => ignore_all_asserts(true),
        AssertAction::Throw => {
            throw_exception(AssertionException::new(
                file, line, function, expression, Some(&message_buffer),
            ));
        }
        _ => {}
    }

    AssertAction::None
}

pub fn ignore_all_asserts(value: bool) {
    unsafe {
        IGNORE_ALL = value;
    }
}

pub fn should_ignore_all_asserts() -> bool {
    unsafe { IGNORE_ALL }
}

static mut IGNORE_ALL: bool = false;

pub fn example_usage() {
    let file = "example.rs";
    let line = 42;
    let function = "main";
    let expr = "1 + 1 == 3";
    let level = AssertLevel::Error as i32;
    let mut ignore_line = false;
    let message = Some("This is a test assert message");

    let action = handle_assert(
        file,
        line,
        function,
        expr,
        level,
        &mut ignore_line,
        message,
    );

    match action {
        AssertAction::Abort => std::process::abort(),
        AssertAction::Throw => println!("Exception thrown"),
        _ => println!("No action"),
    }
}

fn main() {
    example_usage();
}

