    let mut writer: Vec<u8> = Vec::new();
    write!(&mut writer, "{}", args).map_err(|_| std::fmt::Error)?;
    if writer.len() <= buffer.len() {
        buffer[..writer.len()].copy_from_slice(&writer);
        Ok(writer.len())
    } else {
        Err(std::fmt::Error)
    }
}

