struct AssertionException {
    _file: String,
    _line: i32,
    _function: String,
    _expression: String,
    _stack: ManuallyDrop<Vec<u8>>,
    _heap: ManuallyDrop<Option<Box<[u8]>>>,
}

impl AssertionException {
    const SIZE: usize = PPK_ASSERT_EXCEPTION_MESSAGE_BUFFER_SIZE;

    fn new(
        file: &str,
        line: i32,
        function: &str,
        expression: &str,
        message: Option<&str>,
    ) -> Self {
        let (stack, heap) = match message {
            Some(msg) => {
                let length = msg.len();
                if length < Self::SIZE {
                    let mut stack = vec![0; Self::SIZE];
                    stack[..length].copy_from_slice(msg.as_bytes());
                    (ManuallyDrop::new(stack), ManuallyDrop::new(None))
                } else {
                    let heap = Vec::with_capacity(length + 1);
                    (ManuallyDrop::new(vec![0; Self::SIZE]), ManuallyDrop::new(Some(heap.into_boxed_slice())))
                }
            }
            None => (ManuallyDrop::new(vec![0; Self::SIZE]), ManuallyDrop::new(None)),
        };

        AssertionException {
            _file: file.to_string(),
            _line: line,
            _function: function.to_string(),
            _expression: expression.to_string(),
            _stack: stack,
            _heap: heap,
        }
    }

    fn what(&self) -> &str {
        match &*self._heap {
            Some(heap) => std::str::from_utf8(heap).unwrap_or(""),
            None => std::str::from_utf8(&self._stack).unwrap_or(""),
        }
    }
}

impl Drop for AssertionException {
    fn drop(&mut self) {
        if self._heap.is_some() {
            self._heap.take();
        }
    }
}

