trait PrintHandler {
    fn print(&self, level: i32, args: Arguments) -> i32;
}

#[derive(Copy, Clone)]
enum AssertLevel {
    Debug,
    Warning,
    Error,
    Fatal,
}

#[derive(Copy, Clone)]
enum AssertAction {
    None,
    Abort,
    Break,
    Ignore,
    IgnoreLine,
    IgnoreAll,
    Throw,
}

struct AssertionException {
    file: &'static str,
    line: u32,
    function: &'static str,
    expression: Option<&'static str>,
    message: Option<String>,
}

impl AssertionException {
    fn what(&self) -> &str {
        self.message.as_deref().unwrap_or("")
    }
}

lazy_static! {
    static ref IGNORED_ALL: Mutex<bool> = Mutex::new(false);
    static ref HANDLER: Mutex<AssertHandler> = Mutex::new(default_handler);
}

type AssertHandler = fn(&str, u32, &str, &str, i32, Option<&str>) -> AssertAction;
type PrintHandlerFunc = fn(i32, Arguments) -> i32;

fn default_handler(
    file: &str,
    line: u32,
    function: &str,
    expression: &str,
    level: i32,
    message: Option<&str>,
) -> AssertAction {
    let stderr = io::stderr();
    let mut stderr_lock = stderr.lock();

    let print_handler: fn(i32, Arguments) -> i32 = |_level, args| {
        let mut stderr_lock = io::stderr().lock();
        writeln!(stderr_lock, "{}", args).unwrap();
        0
    };

    format_level(level, expression, &print_handler);

    eprintln!("  in file {}, line {}", file, line);
    eprintln!("  function: {}", function);

    if let Some(msg) = message {
        eprintln!("  with message: {}", msg);
    }

    if level < AssertLevel::Debug as i32 {
        AssertAction::None
    } else if AssertLevel::Debug as i32 <= level && level < AssertLevel::Error as i32 {
        let stdin = io::stdin();
        let mut buffer = String::new();

        for _ in 0.. {
            eprint!(
                "Press (I)gnore / Ignore (A)ll / (D)ebug / A(b)ort: "
            );
            stderr_lock.flush().unwrap();
            buffer.clear();
            stdin.lock().read_line(&mut buffer).unwrap();

            match buffer.trim().to_uppercase().as_str() {
                "B" => return AssertAction::Abort,
                "D" => return AssertAction::Break,
                "I" => return AssertAction::Ignore,
                "A" => return AssertAction::IgnoreAll,
                _ => continue,
            }
        }
        AssertAction::Break
    } else if AssertLevel::Error as i32 <= level && level < AssertLevel::Fatal as i32 {
        AssertAction::Throw
    } else {
        AssertAction::Abort
    }
}

impl PrintHandler for fn(i32, Arguments) -> i32 {
    fn print(&self, level: i32, args: Arguments) -> i32 {
        (self)(level, args)
    }
}

fn format_level(level: i32, expression: &str, print_handler: &dyn PrintHandler) {
    let levelstr = match level {
        level if level == AssertLevel::Debug as i32 => "DEBUG",
        level if level == AssertLevel::Warning as i32 => "WARNING",
        level if level == AssertLevel::Error as i32 => "ERROR",
        level if level == AssertLevel::Fatal as i32 => "FATAL",
        _ => "UNKNOWN",
    };

    print_handler.print(
        level,
        format_args!("Assertion '{}' failed ({})", expression, levelstr),
    );
}

fn set_assert_handler(handler: Option<AssertHandler>) -> AssertHandler {
    let mut handler_lock = HANDLER.lock().unwrap();
    let previous = *handler_lock;
    *handler_lock = handler.unwrap_or(default_handler);
    previous
}

fn handle_assert(
    file: &str,
    line: u32,
    function: &str,
    expression: &str,
    level: i32,
    ignore_line: &mut bool,
    message: Option<&str>,
) -> AssertAction {
    let message = message.map(|msg| {
        if msg.len() < 256 {
            msg.to_string()
        } else {
            msg.chars().take(255).collect::<String>()
        }
    });

    let action: AssertAction;
    {
        let handler_lock = HANDLER.lock().unwrap();
        action = handler_lock(file, line, function, expression, level, message.as_deref());
    }

    match action {
        AssertAction::Abort => PPK_ASSERT_ABORT(),
        AssertAction::IgnoreAll => {
            let mut ignored_all = IGNORED_ALL.lock().unwrap();
            *ignored_all = true;
        }
        AssertAction::Throw => {
            throw_assertion_exception(file, line, function, expression, &message.unwrap_or_default())
        }
        _ => {}
    }

    action
}

