#[derive(Debug, PartialEq)]
enum AssertLevel {
    Debug,
    Warning,
    Error,
    Fatal,
}

enum AssertAction {
    None,
    Abort,
    Break,
    Ignore,
    IgnoreLine,
    IgnoreAll,
    Throw,
}

type PrintHandler = fn(&mut dyn Write, i32, &str) -> i32;

static IGNORE_ALL: AtomicBool = AtomicBool::new(false);
static HANDLER: OnceLock<Mutex<Box<dyn Fn(&str, i32, &str, &str, i32, Option<&str>) -> AssertAction + Send + Sync>>> = OnceLock::new();

const MESSAGE_BUFFER_SIZE: usize = 1024;

fn print(out: &mut dyn Write, level: i32, format: &str) -> i32 {
    let formatted_message = format!("[Level {}]: {}", level, format);

    write!(out, "{}", formatted_message).unwrap();
    out.flush().unwrap();

    formatted_message.len() as i32
}

fn format_level(level: i32, expression: &str, out: &mut dyn Write, print: PrintHandler) -> i32 {
    let level_str = match level {
        level if level == AssertLevel::Debug as i32 => "DEBUG",
        level if level == AssertLevel::Warning as i32 => "WARNING",
        level if level == AssertLevel::Error as i32 => "ERROR",
        level if level == AssertLevel::Fatal as i32 => "FATAL",
        _ => return print(out, level, &format!("Assertion '{}' failed (level = {})\n", expression, level)),
    };

    print(out, level, &format!("Assertion '{}' failed ({})\n", expression, level_str))
}

fn default_handler(
    file: &str,
    line: i32,
    function: &str,
    expression: &str,
    level: i32,
    message: Option<&str>,
) -> AssertAction {
    format_level(level, expression, &mut io::stderr(), print);
    print(
        &mut io::stderr(),
        level,
        &format!("  in file {}, line {}\n  function: {}\n", file, line, function),
    );

    if let Some(message) = message {
        print(
            &mut io::stderr(),
            level,
            &format!("  with message: {}\n\n", message),
        );
    }

    if level < AssertLevel::Debug as i32 {
        return AssertAction::None;
    } else if AssertLevel::Debug as i32 <= level && level < AssertLevel::Error as i32 {
        read_user_input()
    } else if AssertLevel::Error as i32 <= level && level < AssertLevel::Fatal as i32 {
        AssertAction::Throw
    } else {
        AssertAction::Abort
    }
}

fn read_user_input() -> AssertAction {
    loop {
        print!(
            &mut io::stderr(),
            0,
            "Press (I)gnore / Ignore (A)ll / (D)ebug / A(b)ort: "
        );

        io::stderr().flush().unwrap();

        let mut buffer = String::new();
        io::stdin().read_line(&mut buffer).unwrap();

        let input = buffer.trim().chars().next().unwrap_or('b');

        match input {
            'b' | 'B' => return AssertAction::Abort,
            'd' | 'D' => return AssertAction::Break,
            'i' | 'I' => return AssertAction::Ignore,
            'a' | 'A' => return AssertAction::IgnoreAll,
            _ => continue,
        }
    }
}

fn handle_assert(
    file: &str,
    line: i32,
    function: &str,
    expression: &str,
    level: i32,
    ignore_line: &mut bool,
    message: Option<&str>
) -> AssertAction {
    let file_trimmed = if cfg!(windows) {
        file.rsplit('\\').next().unwrap_or(file)
    } else {
        file.rsplit('/').next().unwrap_or(file)
    };

    let handler = HANDLER.get_or_init(|| Mutex::new(Box::new(default_handler)));
    let action = (handler.lock().unwrap())(file_trimmed, line, function, expression, level, message);

    match action {
        AssertAction::Abort => {
            abort();
        }
        AssertAction::IgnoreLine => {
            *ignore_line = true;
            AssertAction::None
        }
        AssertAction::IgnoreAll => {
            IGNORE_ALL.store(true, Ordering::SeqCst);
            AssertAction::None
        }
        AssertAction::Throw => panic!("Throwing exception"),
        _ => action,
    }
}

fn set_assert_handler(handler: Box<dyn Fn(&str, i32, &str, &str, i32, Option<&str>) -> AssertAction + Send + Sync>) -> Box<dyn Fn(&str, i32, &str, &str, i32, Option<&str>) -> AssertAction + Send + Sync> {
    let handler_lock = HANDLER.get_or_init(|| Mutex::new(Box::new(default_handler)));
    let mut current_handler = handler_lock.lock().unwrap();
    let previous_handler = std::mem::replace(&mut *current_handler, handler);
    previous_handler
}

fn main() {
    let my_handler: Box<dyn Fn(&str, i32, &str, &str, i32, Option<&str>) -> AssertAction + Send + Sync> = Box::new(|file, line, function, expression, level, message| {
        println!(
            "Custom handler - File: {}, Line: {}, Function: {}, Expression: {}, Level: {}, Message: {:?}",
            file, line, function, expression, level, message
        );
        AssertAction::Ignore
    });

    set_assert_handler(my_handler);
}

